const imageUrl = $json.source_url;

// If running a local WordPress instance behind ngrok/Cloudflare tunnel,
// replace local development URL with public-facing URL:
const publicUrl = imageUrl.replace(
  "https://your-local-site.local",
  "https://YOUR-PUBLIC-WORDPRESS-DOMAIN.com"
);

return {
  image_url: publicUrl
};

const order = $json;

// Handle products safely
const productsData = typeof order.products === "string"
  ? JSON.parse(order.products)
  : order.products || [];

// Currency formatter
const formatMoney = (amount) => {
  return Number(amount).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
};

// Generate product rows
const products = productsData.map(product => `
<tr>
  <td>${product.name || "Product"}</td>
  <td class="center">${product.quantity || 0}</td>
  <td>BDT ${formatMoney(product.price)}</td>
  <td>BDT ${formatMoney(product.total)}</td>
</tr>
`).join("");


// Current date
const invoiceDate = new Date().toLocaleDateString("en-GB");


const html = `
<!DOCTYPE html>
<html>

<head>

<meta charset="UTF-8">

<style>

@page {
  size: A4;
  margin: 20mm;
}

body {
  font-family: Arial, Helvetica, sans-serif;
  color: #333;
  margin: 0;
  padding: 0;
}

.invoice {
  width: 100%;
  max-width: 800px;
  margin: auto;
}


.header {
  text-align: center;
  margin-bottom: 30px;
}


.header h1 {
  font-size: 32px;
  margin: 0;
}


.header p {
  margin: 5px 0;
  color: #666;
}



.info {
  margin-bottom: 30px;
  font-size: 14px;
}


.info p {
  margin: 5px 0;
}



table {

  width:100%;
  border-collapse:collapse;
  margin-top:20px;

}


th {

  background:#f3f3f3;
  font-weight:bold;

}


th, td {

  border:1px solid #ddd;
  padding:12px;
  font-size:14px;

}


.center {

  text-align:center;

}


.total-box {

  margin-top:25px;
  text-align:right;
  font-size:22px;
  font-weight:bold;

}


.payment {

  margin-top:20px;
  font-size:14px;

}


.footer {

  margin-top:60px;
  text-align:center;
  font-size:12px;
  color:#777;

}


</style>

</head>


<body>


<div class="invoice">


<div class="header">

<h1>INVOICE</h1>

<p>AI Ecommerce</p>

</div>



<div class="info">


<p>
<b>Invoice ID:</b> #${order.order_id}
</p>


<p>
<b>Date:</b> ${invoiceDate}
</p>


<p>
<b>Customer:</b> ${order.customer_name || "N/A"}
</p>


<p>
<b>Email:</b> ${order.customer_email || "N/A"}
</p>


<p>
<b>Address:</b> ${order.address || "N/A"}
</p>


</div>




<table>


<tr>

<th>Product</th>

<th>Quantity</th>

<th>Price</th>

<th>Total</th>

</tr>


${products}


</table>



<div class="total-box">

Total Amount: BDT ${formatMoney(order.total)}

</div>



<div class="payment">

<b>Payment Method:</b> ${order.payment_method || "N/A"}

</div>



<div class="footer">

Thank you for your purchase ❤️

</div>



</div>


</body>

</html>
`;



return [
  {
    json: {
      invoice_html: html,
      order_id: order.order_id,
      customer_email: order.customer_email
    }
  }
];

